def serialize(node, out):
    if node is None:
        out.append("#")
        return
    out.append(str(node.val))
    serialize(node.left, out)
    serialize(node.right, out)


def deserialize(data):
    tokens = iter(data.split(","))

    def build():
        token = next(tokens)
        if token == "#":
            return None
        node = TreeNode(int(token))
        node.left = build()
        node.right = build()
        return node

    return build()


